export function ForeignPresentation({ client, pricesVisible, showSafar, showAmanah, presenter }: { client?: string; pricesVisible: boolean; showSafar: boolean; showAmanah: boolean; presenter: boolean }) {
  const [lang, setLang] = useState<Lang>("en"); const t = COPY[lang]; const packs = PACKAGES[lang];
  const [slide, setSlide] = useState(0); const [isFullscreen, setIsFullscreen] = useState(false); const [settingsOpen, setSettingsOpen] = useState(false); const [selected, setSelected] = useState({ safar: showSafar, amanah: showAmanah }); const [showPrices, setShowPrices] = useState(pricesVisible); const [packagePrices, setPackagePrices] = useState({ safar: PRICES.safar, amanah: PRICES.amanah }); const [custom, setCustom] = useState<Package | null>(null); const deckRef = useRef<HTMLDivElement>(null); const touchStart = useRef<number | null>(null);
  const greeting = client ? t.greeting(client) : t.greetingDefault;
  const availablePackages = useMemo(() => {
    const tailoredPackage: Package = custom ?? packs.tailored;
    return [...(selected.safar ? [{ ...packs.safar, price: packagePrices.safar }] : []), ...(selected.amanah ? [{ ...packs.amanah, price: packagePrices.amanah }] : []), tailoredPackage];
  }, [custom, packagePrices, packs, selected]);
  const slides = useMemo(() => [<TitleSlide key="welcome" greeting={greeting} t={t} />, <WhySlide key="why" t={t} />, <OutcomeSlide key="outcome" t={t} />, <ExperienceSlide key="experience" t={t} />, <ProcessSlide key="process" pricesVisible={showPrices} t={t} />, ...(availablePackages.length ? [<PackageSelectorSlide key="packages" items={availablePackages} pricesVisible={showPrices} t={t} />] : []), <ReassuranceSlide key="reassurance" t={t} />, <CloseSlide key="close" t={t} />], [availablePackages, greeting, showPrices, t]);
  const go = useCallback((next: number) => setSlide(Math.min(Math.max(next, 0), slides.length - 1)), [slides.length]);
  const toggleFullscreen = useCallback(async () => { if (!document.fullscreenElement) await deckRef.current?.requestFullscreen(); else await document.exitFullscreen(); }, []);
  useEffect(() => { const onKey = (event: KeyboardEvent) => { if (["ArrowRight", "ArrowDown", " ", "Enter"].includes(event.key)) { event.preventDefault(); go(slide + 1); } if (["ArrowLeft", "ArrowUp"].includes(event.key)) { event.preventDefault(); go(slide - 1); } if (event.key === "f" || event.key === "F") void toggleFullscreen(); if (event.key === "Escape" && document.fullscreenElement) void document.exitFullscreen(); }; const onFullscreen = () => setIsFullscreen(Boolean(document.fullscreenElement)); window.addEventListener("keydown", onKey); document.addEventListener("fullscreenchange", onFullscreen); return () => { window.removeEventListener("keydown", onKey); document.removeEventListener("fullscreenchange", onFullscreen); }; }, [go, slide, toggleFullscreen]);
  useEffect(() => setSlide((current) => Math.min(current, slides.length - 1)), [slides.length]);
  return <div ref={deckRef} className="relative h-[100svh] min-h-[620px] overflow-hidden bg-[#fff6f9] font-sans text-[#102457]" onTouchStart={(e) => { touchStart.current = e.changedTouches[0].clientX; }} onTouchEnd={(e) => { if (touchStart.current === null) return; const distance = e.changedTouches[0].clientX - touchStart.current; if (Math.abs(distance) > 50) go(slide + (distance < 0 ? 1 : -1)); touchStart.current = null; }}><div className="absolute inset-0 bg-[radial-gradient(circle_at_12%_12%,rgba(216,91,135,.26),transparent_25%),radial-gradient(circle_at_85%_82%,rgba(93,140,255,.16),transparent_26%)]" /><div className="relative flex h-full flex-col"><header className="z-20 flex items-center justify-between px-6 py-5 sm:px-10"><Image src="/jodohmu-logo.png" alt="Jodohmu" width={45} height={45} className="h-10 w-10 object-contain " priority /><p className="hidden text-xs font-bold uppercase tracking-[.24em] text-[#102457]/65 sm:block">{t.tagline}</p><div className="flex gap-2">{presenter && <button onClick={() => setSettingsOpen(true)} className="inline-flex items-center gap-2 rounded-full bg-[#d72d62] px-3 py-2 text-xs font-bold text-white"><Settings2 className="h-4 w-4" /><span className="hidden sm:inline">{t.presenterTools}</span></button>}<div role="group" aria-label={t.langLabel} className="inline-flex items-center gap-1 rounded-full border border-[#f0cfdc] py-1 pl-2.5 pr-1 text-xs font-semibold"><Languages className="mr-1 h-4 w-4 text-[#102457]/65" />{(["id", "en"] as const).map((code) => <button key={code} type="button" onClick={() => setLang(code)} aria-pressed={lang === code} className={`rounded-full px-2.5 py-1 transition ${lang === code ? "bg-[#102457] text-white" : "text-[#102457]/75 hover:bg-[#fde8ef] hover:text-[#102457]"}`}>{code.toUpperCase()}</button>)}</div><button onClick={() => void toggleFullscreen()} className="inline-flex items-center gap-2 rounded-full border border-[#f0cfdc] px-3 py-2 text-xs font-semibold text-[#102457]/85 transition hover:bg-[#fde8ef] hover:text-[#102457]" aria-label="Toggle full screen"><Expand className="h-4 w-4" /><span className="hidden sm:inline">{isFullscreen ? t.exitFullscreen : t.fullscreen}</span></button></div></header><div className="relative flex flex-1 items-center overflow-hidden"><div className="flex h-full w-full transition-transform duration-700 ease-[cubic-bezier(.22,1,.36,1)]" style={{ transform: `translateX(-${slide * 100}%)` }}>{slides.map((content, index) => <section key={index} aria-hidden={slide !== index} className="flex h-full w-full shrink-0 items-center justify-center px-7 pb-20 pt-2 sm:px-16 lg:px-24">{content}</section>)}</div></div><footer className="z-20 flex items-center justify-between px-6 pb-6 sm:px-10 sm:pb-8"><div className="flex gap-2">{slides.map((_, index) => <button aria-label={t.goToSlide(index + 1)} onClick={() => go(index)} key={index} className={`h-1.5 rounded-full transition-all ${index === slide ? "w-8 bg-[#d72d62]" : "w-1.5 bg-[#f6c3d4] hover:bg-[#e79ab5]"}`} />)}</div><p className="hidden text-xs text-[#102457]/55 sm:block">{t.navHint}</p><div className="flex gap-2"><button onClick={() => go(slide - 1)} disabled={slide === 0} className="grid h-10 w-10 place-items-center rounded-full border border-[#f0cfdc] text-[#102457] transition hover:bg-[#fde8ef] disabled:cursor-not-allowed disabled:opacity-30" aria-label={t.prevSlide}><ArrowLeft className="h-4 w-4" /></button><button onClick={() => go(slide + 1)} disabled={slide === slides.length - 1} className="grid h-10 w-10 place-items-center rounded-full bg-[#d85b87] text-[#102457] transition hover:bg-[#c44874] disabled:cursor-not-allowed disabled:opacity-40 !text-white" aria-label={t.nextSlide}><ArrowRight className="h-4 w-4" /></button></div></footer></div>{settingsOpen && <PresenterTools selected={selected} setSelected={setSelected} showPrices={showPrices} setShowPrices={setShowPrices} packagePrices={packagePrices} setPackagePrices={setPackagePrices} custom={custom} setCustom={setCustom} onClose={() => setSettingsOpen(false)} t={t} />}</div>;
}

function TitleSlide({ greeting, t }: { greeting: string; t: Copy }) { return <div className="mx-auto max-w-5xl text-center"><p className="text-xs font-bold uppercase tracking-[.28em] text-[#d72d62]">{greeting}</p><h1 className="mx-auto mt-8 max-w-4xl font-serif text-5xl font-bold leading-[1.05] tracking-tight sm:text-7xl lg:text-8xl">{t.title.headA}<span className="italic text-[#d72d62]">{t.title.headB}</span></h1><p className="mx-auto mt-8 max-w-2xl text-lg leading-8 text-[#102457]/80 sm:text-xl">{t.title.sub}</p><div className="mt-12 flex justify-center"><ChevronDown className="h-6 w-6 animate-bounce text-[#d72d62]" /></div></div>; }
function WhySlide({ t }: { t: Copy }) { const icons = [ShieldCheck, Users, Heart]; const items = t.why.items.map(([title, text], index) => [icons[index], title, text] as const); return <div className="mx-auto w-full max-w-6xl"><p className="text-center text-xs font-bold uppercase tracking-[.25em] text-[#d72d62]">{t.why.eyebrow}</p><h2 className="mt-3 text-center font-serif text-4xl font-bold sm:text-6xl">{t.why.head}</h2><div className="mt-7 grid gap-5 lg:grid-cols-[1.12fr_.88fr] lg:items-stretch"><div className="relative min-h-[330px] overflow-hidden rounded-3xl border border-[#f0cfdc] shadow-xl shadow-[#c0486f]/15"><Image src="/presentations-foreign-cindo-family.png" alt={t.why.alt} fill className="object-cover" sizes="(max-width: 1024px) 95vw, 640px" /><div className="absolute inset-0 bg-[linear-gradient(90deg,rgba(255,244,248,.54),transparent_62%)]" /><p className="absolute bottom-6 left-6 max-w-[15rem] font-serif text-2xl font-bold leading-tight text-[#102457]">{t.why.overlayA}<span className="italic text-[#c62d5c]">{t.why.overlayB}</span></p></div><div className="grid gap-3 sm:grid-cols-3 lg:grid-cols-1">{items.map(([Icon, title, text]) => { const ItemIcon = Icon as typeof ShieldCheck; return <div key={String(title)} className="rounded-2xl border border-[#f0cfdc] bg-white/80 p-5 backdrop-blur"><ItemIcon className="h-7 w-7 text-[#d72d62]" /><h3 className="mt-3 text-lg font-bold">{title as string}</h3><p className="mt-2 text-sm leading-5 text-[#102457]/75">{text as string}</p></div>; })}</div></div></div>; }
function OutcomeSlide({ t }: { t: Copy }) { return <div className="mx-auto grid w-full max-w-6xl gap-10 lg:grid-cols-[1fr_.9fr] lg:items-center"><div><p className="text-xs font-bold uppercase tracking-[.25em] text-[#d72d62]">{t.outcome.eyebrow}</p><h2 className="mt-5 font-serif text-5xl font-bold leading-tight sm:text-7xl">{t.outcome.headA}<br /><span className="italic text-[#d72d62]">{t.outcome.headB}</span></h2><p className="mt-7 max-w-xl text-lg leading-8 text-[#102457]/80">{t.outcome.para}</p></div><div className="space-y-4">{t.outcome.items.map((text, index) => <div key={index} className="flex gap-5 rounded-2xl border border-[#f0cfdc] bg-white/80 p-5"><span className="font-serif text-2xl text-[#d72d62]">0{index + 1}</span><p className="leading-7 text-[#102457]/85">{text}</p></div>)}</div></div>; }
function ProcessSlide({ pricesVisible, t }: { pricesVisible: boolean; t: Copy }) { const [active, setActive] = useState(0); const stages = t.process.stages; const current = stages[active]; return <div className="mx-auto -mt-8 w-full max-w-6xl"><p className="text-center text-xs font-bold uppercase tracking-[.25em] text-[#d72d62]">{t.process.eyebrow}</p><h2 className="mt-2 text-center font-serif text-4xl font-bold leading-tight sm:text-5xl">{t.process.head}</h2><p className="mx-auto mt-3 max-w-2xl text-center leading-6 text-[#102457]/75">{t.process.sub}</p><div className="mt-7 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">{stages.map((stage, index) => <button key={stage.title} onClick={() => setActive(index)} className={`group relative min-h-[118px] overflow-hidden rounded-2xl border p-4 text-left transition duration-300 ${active === index ? "border-[#d72d62] bg-[linear-gradient(145deg,rgba(216,45,98,.12),rgba(255,255,255,.92))] shadow-lg shadow-[#c0486f]/15" : "border-[#f0cfdc] bg-white/80 hover:-translate-y-1 hover:border-[#e79ab5] hover:bg-white"}`}><span className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.14em] ${active === index ? "bg-[#d72d62] text-white" : "bg-[#fde8ef] text-[#102457]/70"}`}>{t.process.stageLabel(index + 1)}</span><p className="mt-4 pr-4 text-sm font-bold leading-5">{stage.title}</p>{index < stages.length - 1 && <ArrowRight className={`absolute bottom-4 right-3 h-4 w-4 transition ${active === index ? "text-[#d72d62]" : "text-[#102457]/35 group-hover:translate-x-1 group-hover:text-[#102457]/70"}`} />}</button>)}</div><div className="mt-5 rounded-3xl border border-[#f0cfdc] bg-white/80 p-6 sm:grid sm:grid-cols-[.7fr_1.3fr] sm:gap-10 sm:p-8"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-[#d72d62]">{t.process.stageLabel(active + 1)} · {current.short}</p><h3 className="mt-2 font-serif text-3xl font-bold leading-tight">{current.title}</h3>{pricesVisible && current.payment && <span className="mt-4 inline-flex rounded-full border border-[#d72d62]/50 bg-[#d72d62]/10 px-3 py-1 text-xs font-bold text-[#d72d62]">{current.payment}</span>}</div><div className="mt-5 sm:mt-0"><ul className="space-y-2.5">{current.points.map((point) => <li key={point} className="flex items-start gap-3 leading-6 text-[#102457]/85"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-[#ef91b1]" />{point}</li>)}</ul><p className="mt-5 border-l-2 border-[#ef91b1] pl-4 text-sm font-bold leading-6 text-[#c62d5c]">{current.outcome}</p></div></div><p className="mt-4 text-center text-xs text-[#102457]/55">{t.process.hint}</p></div>; }
function ExperienceSlide({ t }: { t: Copy }) { return <div className="mx-auto w-full max-w-6xl text-center"><p className="text-xs font-bold uppercase tracking-[.25em] text-[#d72d62]">{t.experience.eyebrow}</p><h2 className="mt-4 font-serif text-4xl font-bold leading-tight sm:text-6xl">{t.experience.head}</h2><div className="relative mx-auto mt-8 aspect-video w-full max-w-5xl overflow-hidden rounded-[2rem] border border-[#f0cfdc] shadow-2xl shadow-[#c0486f]/15"><Image src="/presentations-foreign-muslim-journey-centered.png" alt={t.experience.alt} fill className="object-cover" sizes="(max-width: 1024px) 95vw, 1024px" /><div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-[#fff6f9] via-[#fff6f9]/90 to-transparent px-7 pb-7 pt-24 sm:px-10 sm:pb-9"><p className="mx-auto max-w-xl text-base leading-7 text-[#102457]/90">{t.experience.para}</p><p className="mt-3 text-xs font-bold uppercase tracking-[.18em] text-[#d72d62]">{t.experience.tag}</p></div></div></div>; }
function PackageSelectorSlide({ items, pricesVisible, t }: { items: Package[]; pricesVisible: boolean; t: Copy }) { const [active, setActive] = useState<string | null>(null); const [mounted, setMounted] = useState(false); useEffect(() => { setMounted(true); }, []); useEffect(() => { if (!active) return; const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") setActive(null); }; document.addEventListener("keydown", onKey); const previous = document.body.style.overflow; document.body.style.overflow = "hidden"; return () => { document.removeEventListener("keydown", onKey); document.body.style.overflow = previous; }; }, [active]); const selectedPackage = items.find((item) => item.name === active); const isTailored = selectedPackage && selectedPackage.name !== "Safar" && selectedPackage.name !== "Amanah"; const cardCopyFor = (item: Package) => item.name === "Safar" ? t.packages.cards.safar : item.name === "Amanah" ? t.packages.cards.amanah : t.packages.cards.tailored; const cardTitle = (item: Package) => cardCopyFor(item)[0]; const cardCopy = (item: Package) => cardCopyFor(item)[1]; return <div className="mx-auto w-full max-w-6xl"><p className="text-center text-xs font-bold uppercase tracking-[.25em] text-[#d72d62]">{t.packages.eyebrow}</p><h2 className="mt-2 text-center font-serif text-4xl font-bold sm:text-5xl">{t.packages.head}</h2><p className="mx-auto mt-2 max-w-2xl text-center leading-6 text-[#102457]/75">{t.packages.sub}</p><div className={`mx-auto mt-6 grid max-w-4xl gap-3 ${items.length === 1 ? "max-w-sm" : items.length === 2 ? "sm:grid-cols-2" : items.length === 4 ? "max-w-3xl sm:grid-cols-2" : "sm:grid-cols-3"}`}>{items.map((item) => <button key={item.name} onClick={() => setActive((current) => current === item.name ? null : item.name)} className={`rounded-2xl border p-4 text-left transition duration-300 ${active === item.name ? "border-[#d72d62] bg-white shadow-xl shadow-[#c0486f]/15" : "border-[#f0cfdc] bg-white/80 hover:-translate-y-1 hover:border-[#e79ab5] hover:bg-white"}`}><span className="block h-1.5 w-10 rounded-full" style={{ backgroundColor: item.accent }} /><h3 className="mt-4 text-lg font-bold leading-tight">{cardTitle(item)}</h3><p className="mt-1 text-xs leading-5 text-[#102457]/70">{cardCopy(item)}</p><p className="mt-4 text-xs font-bold uppercase tracking-[.14em] text-[#102457]/55">{active === item.name ? t.packages.close : t.packages.view}</p></button>)}</div>{selectedPackage && mounted && createPortal(<div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-[#3a1d2e]/45 p-4 backdrop-blur-sm sm:items-center sm:p-8" onClick={() => setActive(null)}><div role="dialog" aria-modal="true" aria-label={selectedPackage.name} onClick={(event) => event.stopPropagation()} className="relative my-auto flex max-h-[92svh] w-full max-w-3xl flex-col overflow-hidden rounded-3xl border border-[#f0cfdc] bg-white text-left font-sans text-[#102457] shadow-2xl shadow-[#c0486f]/15"><button type="button" onClick={() => setActive(null)} aria-label={t.packages.close} className="absolute right-4 top-4 z-10 grid h-9 w-9 place-items-center rounded-full border border-[#f0cfdc] bg-[#fde8ef] text-[#102457]/85 transition hover:bg-[#fbd5e2] hover:text-[#102457]"><X className="h-4 w-4" /></button><div className="overflow-y-auto px-6 py-7 sm:px-8">{isTailored ? <TailoredPlanBuilder t={t} /> : <><div className="flex flex-col gap-4 pr-10 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em]" style={{ color: selectedPackage.accent }}>{selectedPackage.label}</p><h3 className="mt-2 font-serif text-3xl font-bold">{selectedPackage.name}</h3><p className="mt-2 max-w-2xl leading-6 text-[#102457]/80">{selectedPackage.description}</p></div>{pricesVisible && <div className="shrink-0 sm:text-right"><p className="text-3xl font-bold" style={{ color: selectedPackage.accent }}>{selectedPackage.price}</p></div>}</div><div className="mt-6 border-t border-[#f0cfdc] pt-5"><p className="text-xs font-bold uppercase tracking-[.18em] text-[#102457]/55">{t.packages.journey}</p><StagedFeatures pkg={selectedPackage} t={t} /></div></>}</div></div></div>, document.body)}</div>; }

function StagedFeatures({ pkg, t }: { pkg: Package; t: Copy }) { if (!pkg.stages) return <ol className="mt-3 space-y-2.5">{(pkg.features ?? []).map((feature, i) => <li key={feature} className="flex items-start gap-3 text-sm leading-5 text-[#102457]/90"><span className="mt-px grid h-5 w-5 shrink-0 place-items-center rounded-full text-[11px] font-bold text-white" style={{ backgroundColor: pkg.accent }}>{i + 1}</span>{feature}</li>)}</ol>; return <div className="mt-3">{pkg.includes && <p className="mb-3 text-sm font-bold text-[#102457]/90">{pkg.includes}</p>}<div className="space-y-3">{pkg.stages.map(({ stage, items }) => <div key={stage} className="grid gap-2 rounded-2xl border border-[#f0cfdc] bg-white/80 p-4 sm:grid-cols-[11rem_1fr] sm:gap-4"><div><span className="inline-flex rounded-full px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-[.14em] text-white" style={{ backgroundColor: pkg.accent }}>{t.process.stageLabel(stage)}</span><p className="mt-1.5 text-xs font-bold leading-4 text-[#102457]/70">{t.process.stages[stage - 1].title}</p></div><ul className="space-y-1.5">{items.map((item) => <li key={item} className="flex items-start gap-2.5 text-sm leading-5 text-[#102457]/90"><span className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full" style={{ backgroundColor: pkg.accent }} />{item}</li>)}</ul></div>)}</div></div>; }

function TailoredPlanBuilder({ t }: { t: Copy }) { const options = [{ id: "onboarding", title: t.builder.options.onboarding, price: 200 }, { id: "psychology", title: t.builder.options.psychology, price: 200 }, { id: "background", title: t.builder.options.background, price: 150 }, { id: "online", title: t.builder.options.online, price: 150 }, { id: "family", title: t.builder.options.family, price: 150 }, { id: "indonesia", title: t.builder.options.indonesia, price: 150 }]; const [chosen, setChosen] = useState<string[]>(["onboarding", "online"]); const [order, setOrder] = useState(options.map((option) => option.id)); const [dragging, setDragging] = useState<string | null>(null); const [onlineSessions, setOnlineSessions] = useState(3); const [psychologySessions, setPsychologySessions] = useState(1); const orderedOptions = order.map((id) => options.find((option) => option.id === id)!).filter(Boolean); const toggle = (id: string) => setChosen((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); const changeCount = (setter: React.Dispatch<React.SetStateAction<number>>, amount: number) => setter((count) => Math.max(1, Math.min(12, count + amount))); const moveTo = (target: string) => { if (!dragging || dragging === target) return; setOrder((current) => { const next = current.filter((id) => id !== dragging); next.splice(next.indexOf(target), 0, dragging); return next; }); setDragging(null); }; const lineTotal = (option: { id: string; price: number }) => option.id === "online" ? option.price * onlineSessions : option.id === "psychology" ? option.price * psychologySessions : option.price; const total = orderedOptions.filter((option) => chosen.includes(option.id)).reduce((sum, option) => sum + lineTotal(option), 0); const summary = orderedOptions.filter((option) => chosen.includes(option.id)).map((option) => option.id === "online" ? t.builder.onlineSummary(onlineSessions) : option.id === "psychology" ? t.builder.psychologySummary(psychologySessions) : option.title); return <div className="mx-auto mt-5 max-w-5xl rounded-3xl border border-[#a88ae6]/50 bg-[#a88ae6]/[.09] p-5 text-left sm:p-6"><div className="flex items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-[#6d4fc9]">{t.builder.eyebrow}</p><h3 className="mt-1 font-serif text-2xl font-bold">{t.builder.head}</h3></div><p className="text-xs font-bold text-[#6d4fc9]">{t.builder.selectedCount(chosen.length)}</p></div><p className="mt-1 text-xs text-[#102457]/55">{t.builder.sub}</p><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-3">{orderedOptions.map((option) => { const selected = chosen.includes(option.id); const hasCounter = selected && (option.id === "online" || option.id === "psychology"); const value = option.id === "online" ? onlineSessions : psychologySessions; const setter = option.id === "online" ? setOnlineSessions : setPsychologySessions; return <div key={option.id} draggable onDragStart={() => setDragging(option.id)} onDragEnd={() => setDragging(null)} onDragOver={(event) => event.preventDefault()} onDrop={() => moveTo(option.id)} className={`relative rounded-xl border transition ${dragging === option.id ? "scale-95 opacity-50" : ""} ${selected ? "border-[#c9b6ff] bg-[#a88ae6]/25" : "border-[#f0cfdc] bg-white/80 hover:border-[#e79ab5]"}`}><span className="absolute right-2 top-2 cursor-grab text-xs tracking-[-.18em] text-[#102457]/45" aria-hidden>⋮⋮</span><button onClick={() => toggle(option.id)} className="flex min-h-[54px] w-full items-center gap-3 px-3 py-2 pr-8 text-left"><span className={`grid h-5 w-5 shrink-0 place-items-center rounded-full text-xs font-bold ${selected ? "bg-[#c9b6ff] text-[#211a3b]" : "bg-[#fde8ef] text-[#102457]/55"}`}>{selected ? "✓" : "+"}</span><span><p className="text-xs font-bold leading-4">{option.title}</p><p className="mt-0.5 text-[11px] font-bold text-[#6d4fc9]">${option.price}{option.id === "online" || option.id === "psychology" ? t.builder.each : ""}</p></span></button>{hasCounter && <div className="flex items-center justify-between border-t border-[#c9b6ff]/25 px-3 py-2"><span className="text-[10px] font-bold uppercase tracking-[.12em] text-[#6d4fc9]">{t.builder.howMany}</span><div className="flex items-center gap-2"><button onClick={() => changeCount(setter, -1)} className="grid h-6 w-6 place-items-center rounded-full bg-[#fde8ef] text-sm font-bold hover:bg-[#fbd5e2]" aria-label={t.builder.decrease(option.title)}>−</button><span className="w-4 text-center text-sm font-bold text-[#6d4fc9]">{value}</span><button onClick={() => changeCount(setter, 1)} className="grid h-6 w-6 place-items-center rounded-full bg-[#c9b6ff] text-sm font-bold text-[#211a3b]" aria-label={t.builder.increase(option.title)}>+</button></div></div>}</div>; })}</div><div className="mt-3 rounded-xl bg-[#fde8ef] px-4 py-3"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.16em] text-[#102457]/55">{t.builder.totalLabel}</p>{chosen.length > 0 && <p className="text-sm font-bold text-[#6d4fc9]">${total}</p>}</div><p className="mt-1 text-sm leading-5 text-[#102457]/85">{summary.length ? summary.join(" → ") : t.builder.empty}</p></div></div>; }
function ReassuranceSlide({ t }: { t: Copy }) { const answers = t.faq.items; const [active, setActive] = useState(0); const current = answers[active]; const colors = ["#d72d62","#ef91b1","#7ed6c1","#c9b6ff","#ef91b1","#7ed6c1","#d72d62","#c9b6ff"]; return <div className="mx-auto w-full max-w-6xl"><p className="text-center text-xs font-bold uppercase tracking-[.25em] text-[#d72d62]">{t.faq.eyebrow}</p><h2 className="mt-3 text-center font-serif text-4xl font-bold sm:text-6xl">{t.faq.head}</h2><p className="mx-auto mt-3 max-w-xl text-center text-sm leading-6 text-[#102457]/70">{t.faq.sub}</p><div className="mt-7 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{answers.map(([question], index) => { const color = colors[index]; const open = active === index; return <button key={question} onClick={() => setActive(index)} style={{ borderColor: open ? color : undefined, background: open ? `linear-gradient(135deg,${color}33,rgba(255,255,255,.92))` : undefined }} className={`group relative min-h-[116px] overflow-hidden rounded-2xl border p-4 text-left transition duration-300 ${open ? "-translate-y-1 shadow-xl shadow-[#c0486f]/15" : "border-[#f0cfdc] bg-white/80 hover:-translate-y-1 hover:border-[#e79ab5] hover:bg-white"}`}><span className="absolute -right-5 -top-7 h-20 w-20 rounded-full opacity-20 blur-sm" style={{ backgroundColor: color }} /><div className="relative flex items-start justify-between"><span className="grid h-8 w-8 place-items-center rounded-full text-xs font-black text-[#102457]" style={{ backgroundColor: color }}>0{index + 1}</span><span className={`grid h-7 w-7 place-items-center rounded-full border text-base font-light transition ${open ? "border-[#d72d62]/60 text-[#102457]" : "border-[#f0cfdc] text-[#102457]/65 group-hover:bg-[#fde8ef]"}`}>{open ? "−" : "+"}</span></div><h3 className="relative mt-4 pr-4 text-sm font-bold leading-5">{question}</h3></button>; })}</div><div className="mt-4 overflow-hidden rounded-3xl border border-[#f0cfdc] bg-white/80 sm:grid sm:grid-cols-[.85fr_1.15fr]"><div className="p-6 sm:p-8" style={{ background: `linear-gradient(135deg,${colors[active]}30,transparent)` }}><p className="text-xs font-bold uppercase tracking-[.2em]" style={{ color: colors[active] }}>{t.faq.yourQuestion}</p><h3 className="mt-3 font-serif text-2xl font-bold leading-tight sm:text-3xl">{current[0]}</h3></div><div className="flex items-center p-6 sm:p-8"><p className="leading-7 text-[#102457]/85">{current[1]}</p></div></div></div>; }
function CloseSlide({ t }: { t: Copy }) { return <div className="relative mx-auto w-full max-w-6xl overflow-hidden rounded-[2rem] border border-[#f0cfdc] shadow-2xl shadow-[#c0486f]/15"><Image src="/presentations-foreign-wedding-celebration.png" alt={t.close.alt} fill className="object-cover" sizes="(max-width: 1024px) 95vw, 1152px" priority /><div className="relative min-h-[500px] bg-[linear-gradient(90deg,rgba(255,244,248,.94)_0%,rgba(255,244,248,.78)_42%,rgba(255,244,248,.12)_100%)] p-8 sm:min-h-[540px] sm:p-12"><div className="flex h-full max-w-xl flex-col justify-center text-left"><p className="text-xs font-bold uppercase tracking-[.25em] text-[#d72d62]">{t.close.eyebrow}</p><h2 className="mt-6 font-serif text-4xl font-bold leading-tight sm:text-6xl">{t.close.headA}<span className="italic text-[#d72d62]">{t.close.headB}</span></h2><p className="mt-6 max-w-lg text-base leading-7 text-[#102457]/85 sm:text-lg sm:leading-8">{t.close.para}</p><a href={"https://wa.me/628138858595?text=" + encodeURIComponent(t.whatsapp)} target="_blank" rel="noopener noreferrer" className="mt-9 inline-flex w-fit items-center gap-2 rounded-full bg-[#d85b87] px-7 py-4 font-bold transition hover:bg-[#c44874] !text-white"><MessageCircle className="h-5 w-5" />{t.close.cta}</a></div></div></div>; }

function PresenterTools({ selected, setSelected, showPrices, setShowPrices, packagePrices, setPackagePrices, custom, setCustom, onClose, t }: { selected: { safar: boolean; amanah: boolean }; setSelected: React.Dispatch<React.SetStateAction<{ safar: boolean; amanah: boolean }>>; showPrices: boolean; setShowPrices: React.Dispatch<React.SetStateAction<boolean>>; packagePrices: { safar: string; amanah: string }; setPackagePrices: React.Dispatch<React.SetStateAction<{ safar: string; amanah: string }>>; custom: Package | null; setCustom: React.Dispatch<React.SetStateAction<Package | null>>; onClose: () => void; t: Copy }) { const [name, setName] = useState(custom?.name ?? ""); const [price, setPrice] = useState(custom?.price ?? ""); const [window, setWindow] = useState(custom?.window ?? ""); const [description, setDescription] = useState(custom?.description ?? ""); const [features, setFeatures] = useState(custom?.features.join("\n") ?? ""); const save = () => { if (!name.trim()) return; setCustom({ name: name.trim(), label: t.presenter.customLabel, price: price.trim() || t.presenter.defaultPrice, window: window.trim() || t.presenter.defaultWindow, description: description.trim() || t.presenter.defaultDescription, features: features.split("\n").map((item) => item.trim()).filter(Boolean), accent: "#a88ae6" }); }; return <aside className="absolute inset-y-0 right-0 z-50 w-full max-w-md overflow-y-auto border-l border-[#f0cfdc] bg-white p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-[#d72d62]">{t.presenter.eyebrow}</p><h2 className="mt-2 font-serif text-3xl font-bold">{t.presenter.head}</h2></div><button onClick={onClose} className="rounded-full p-2 hover:bg-[#fde8ef]" aria-label={t.presenter.close}><X className="h-5 w-5" /></button></div><p className="mt-4 text-sm leading-6 text-[#102457]/75">{t.presenter.intro}</p><div className="mt-8 space-y-3"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.18em] text-[#102457]/55">{t.presenter.pricesTitle}</p><label className="flex items-center gap-2 text-xs font-bold text-[#d72d62]">{t.presenter.showPrices} <input type="checkbox" checked={showPrices} onChange={(e) => setShowPrices(e.target.checked)} className="h-4 w-4 accent-[#d85b87]" /></label></div>{([['safar', 'Safar'], ['amanah', 'Amanah']] as const).map(([key, label]) => <div key={key} className="rounded-xl border border-[#f0cfdc] p-4"><div className="flex items-center justify-between"><span className="font-bold">{label}</span><label className="flex items-center gap-2 text-xs text-[#102457]/75">{t.presenter.show} <input type="checkbox" checked={selected[key]} onChange={(e) => setSelected((current) => ({ ...current, [key]: e.target.checked }))} className="h-4 w-4 accent-[#d85b87]" /></label></div><input value={packagePrices[key]} onChange={(e) => setPackagePrices((current) => ({ ...current, [key]: e.target.value }))} placeholder={t.presenter.pricePlaceholder} className="mt-3 w-full rounded-lg border border-[#f0cfdc] bg-white/80 px-3 py-2.5 text-sm outline-none placeholder:text-[#102457]/45 focus:border-[#d72d62]" /></div>)}</div><div className="mt-8 border-t border-[#f0cfdc] pt-7"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.18em] text-[#102457]/55">{t.presenter.customTitle}</p>{custom && <button onClick={() => setCustom(null)} className="text-xs font-bold text-[#d72d62]">{t.presenter.remove}</button>}</div><div className="mt-4 space-y-3"><input value={name} onChange={(e) => setName(e.target.value)} placeholder={t.presenter.namePlaceholder} className="w-full rounded-xl border border-[#f0cfdc] bg-white/80 px-4 py-3 text-sm outline-none placeholder:text-[#102457]/45 focus:border-[#d72d62]" /><div className="grid grid-cols-2 gap-3"><input value={price} onChange={(e) => setPrice(e.target.value)} placeholder={t.presenter.freePricePlaceholder} className="w-full rounded-xl border border-[#f0cfdc] bg-white/80 px-4 py-3 text-sm outline-none placeholder:text-[#102457]/45 focus:border-[#d72d62]" /><input value={window} onChange={(e) => setWindow(e.target.value)} placeholder={t.presenter.durationPlaceholder} className="w-full rounded-xl border border-[#f0cfdc] bg-white/80 px-4 py-3 text-sm outline-none placeholder:text-[#102457]/45 focus:border-[#d72d62]" /></div><textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder={t.presenter.descPlaceholder} rows={3} className="w-full rounded-xl border border-[#f0cfdc] bg-white/80 px-4 py-3 text-sm outline-none placeholder:text-[#102457]/45 focus:border-[#d72d62]" /><textarea value={features} onChange={(e) => setFeatures(e.target.value)} placeholder={t.presenter.featuresPlaceholder} rows={5} className="w-full rounded-xl border border-[#f0cfdc] bg-white/80 px-4 py-3 text-sm outline-none placeholder:text-[#102457]/45 focus:border-[#d72d62]" /><button onClick={save} className="w-full rounded-xl bg-[#a88ae6] px-4 py-3 text-sm font-bold text-[#171129]">{custom ? t.presenter.update : t.presenter.add}</button></div></div></aside>; }
